// Actual native timeline gestures against the existing processing/session model.
void appliedBoundaryChecks(const juce::File& root)
{
    auto req=fixture(root.getChildFile("applied-boundary.wav"),48000,2,240000);StandaloneSessionModel s;
    expect(s.setValidatedSource(req.context.sourceFile,req.context.media),"applied boundary fixture imported");
    s.sourceDocument.layout=req.context.fileLayout;std::shared_ptr<const waveform::Overview> overview;measure(s,Domain::source,&overview);s.synchronizeSections();
    auto before=s.manualState();before.globalDb=3;
    processing::SectionGainPlan plan;plan.inputIdentity=before.map.inputIdentity;plan.sampleRate=48000;plan.frames=240000;
    plan.intervals={{0,48000,0},{48000,96000,-4},{96000,144000,-2},{144000,240000,0}};before.gains=plan;
    expect(s.commitManualEdit(before,"Fixture gains"),"independent applied gains prepared without section boundaries");
    measure(s,Domain::currentState);before=s.manualState();const auto verified=s.currentState.analysis,source=s.source.analysis;
    const auto revision=s.revision,count=s.manualHistory->undoCount();
    TimelineGainLane lane(s);MeasurementTimeline ui;ui.setSize(1150,640);ui.attachGainLane(lane);
    ui.setProgramme(240000,48000,"applied");ui.setWaveform(overview,true,{"L","R"});lane.synchronize("applied");ui.bindSectionEditing(s,[&](uint64_t){lane.synchronize("applied");});ui.setReferenceMeasurement({},true);
    juce::ComboBox* mode=nullptr;for(auto* c:lane.getChildren())if(auto* b=dynamic_cast<juce::ComboBox*>(c))mode=b;
    expect(mode!=nullptr,"explicit section/applied/proposed selection mode");mode->setSelectedId(2,juce::sendNotificationSync);
    ui.addToDesktop(juce::ComponentPeer::windowHasTitleBar);ui.setVisible(true);ui.toFront(true);pump(20);ui.focusForTransport();
    const auto x=[&](int64_t frame){const auto v=ui.viewRange();return float(ui.graphBounds().getX()+(frame-v.first)*(ui.graphBounds().getWidth()-1)/(v.second-v.first));};
    const auto point=[&](int64_t frame){return juce::Point<float>{x(frame),float(lane.getY()+lane.plotBounds().getY()+4)};};
    const auto start=[&](int64_t frame){ui.mouseDown(mouse(ui,point(frame)));};
    const auto move=[&](int64_t frame){ui.mouseDrag(mouse(ui,point(frame)));};
    const auto finish=[&](int64_t frame){ui.mouseUp(mouse(ui,point(frame),false));};
    expect(!lane.appliedBoundaryHandle(point(0).toInt()-lane.getPosition())&&!lane.appliedBoundaryHandle(point(240000).toInt()-lane.getPosition()),"programme endpoints have no movable handles");
    start(48000);finish(48000);
    expect(s.revision==revision&&s.currentState.analysis==verified&&s.manualHistory->undoCount()==count,"clicking a handle without movement preserves verified Current and Undo");
    start(48000);move(60000);
    expect(s.appliedBoundaryDrag&&s.manualState()==before&&s.currentState.analysis==verified&&s.manualHistory->undoCount()==count,"live preview never edits audio or clears measurement authority");
    const auto preview=s.displayedSectionGains();const auto cut=preview->intervals[1].begin;
    expect(std::abs(cut-60000)<=1&&preview->intervals[0].end==cut&&preview->gainAt(54000)==0&&before.gains->gainAt(54000)==-4,"preview moves the real shared envelope cut and changes effective gain");
    expect(ui.transitionSpans().front()==std::make_pair(cut-2400,cut+2400),"waveform preview uses exact moved ramp support");
    expect(s.audioEditsBlocked()&&!s.canUndoManual()&&!s.stageBoundary(0,120000)&&!s.setCurrentGainDb(4),"in-progress drag protects processing and section edits");
    imageOf(ui,root.getChildFile("applied-boundary-preview.png"));
    expect(ui.keyPressed(juce::KeyPress(juce::KeyPress::escapeKey)),"Escape cancels native applied boundary drag");finish(60000);
    expect(!s.appliedBoundaryDrag&&s.manualState()==before&&s.currentState.analysis==verified&&s.revision==revision,"cancelled drag and later mouse-up leave processing and verification intact");
    start(48000);move(60000);move(48000);finish(48000);
    expect(s.manualState()==before&&s.currentState.analysis==verified&&s.manualHistory->undoCount()==count,"out-and-back gesture retains the original sample cut exactly");
    start(48000);move(60000);finish(60000);const auto moved=s.manualState();
    expect(s.manualHistory->undoCount()==count+1&&s.currentStateNeedsRemeasurement()&&!s.currentState.hasMeasurement&&s.source.analysis==source,"one released drag is one Undo and invalidates only Current");
    expect(moved.globalDb==3&&moved.gains->intervals.size()==4&&moved.gains->intervals[1].db==-4&&moved.gains->intervals[2].db==-2&&moved.gains->intervals[2].begin==96000&&s.sectionDocument.map().sections.size()==1,"shared boundary preserves both gains, global gain, other cuts and annotations");
    auto context=s.measurementContext(Domain::currentState);ProgrammeGainProcessor processor(context.processing);
    juce::AudioBuffer<float> samples(2,1);samples.setSample(0,0,.1f);samples.setSample(1,0,.1f);
    expect(processor.process(samples.getArrayOfWritePointers(),2,1,54000)&&samples.getSample(0,0)==float(.1f*std::pow(10.,3./20.))&&samples.getSample(1,0)==samples.getSample(0,0),"real sample processor uses the moved plateau with unchanged global gain on both channels");
    expect(s.undoManual()&&s.manualState()==before&&s.undoManual(true)&&s.manualState()==moved,"Undo/Redo restores exact envelope geometry");
    measure(s,Domain::currentState);expect(!s.currentStateNeedsRemeasurement()&&s.currentState.hasMeasurement&&s.currentState.analysis!=verified,"independent measurement verifies the edited Current");
    expect(s.undoManual()&&s.manualState()==before&&s.currentStateNeedsRemeasurement(),"Undo still works after independent remeasurement and invalidates its authority");s.undoManual(true);
    JobControl job;const auto path=root.getChildFile("edited-boundary.levelscope");
    expect(sessionfile::save(sessionfile::capture(s),path,job).succeeded(),"edited boundary saves through existing session writer");
    const auto read=sessionfile::read(path,job);expect(read.document.has_value(),"edited boundary session reads");auto reopened=sessionfile::verify(*read.document,job);
    expect(reopened.prepared&&reopened.prepared->model.manualState()==moved&&reopened.prepared->model.currentStateNeedsRemeasurement(),"save/reopen preserves exact edited processing and unverified status");
    auto token=s.beginAppliedBoundary(2);expect(token!=0&&s.previewAppliedBoundary(token,0),"shared boundary can be dragged toward neighbour");
    expect(s.displayedSectionGains()->intervals[2].begin==moved.gains->intervals[1].begin+2&&s.displayedSectionGains()->radius(1)==1&&s.displayedSectionGains()->radius(2)==1,"neighbour clamp leaves two samples and resizes both neighbouring ramps using engine rules");
    s.previewAppliedBoundary(token,240000);expect(s.displayedSectionGains()->intervals[1].end==143998&&s.displayedSectionGains()->intervals[3].begin==144000,"drag cannot cross or overwrite the next region");s.cancelAppliedBoundary(token);
    expect(!moveAppliedBoundary(moved,0,1)&&!moveAppliedBoundary(moved,4,239999)&&!moveAppliedBoundary(moved,2,moved.gains->intervals[1].begin+1),"fixed endpoints and zero-radius transitions rejected");
    token=s.beginAppliedBoundary(1);++s.revision;expect(!s.commitAppliedBoundary(token)&&!s.appliedBoundaryDrag&&s.manualState()==moved,"stale revision rejects the completed gesture");
    s.auditionBusy=[]{return true;};expect(!s.beginAppliedBoundary(1),"playing/preparing transport forbids boundary edits");s.auditionBusy={};
    s.persistenceLoading=true;expect(!s.beginAppliedBoundary(1),"loading a session forbids boundary edits");s.persistenceLoading=false;
    s.job.begin(JobStage::analysis,s.revision);expect(!s.beginAppliedBoundary(1),"measurement blocks applied boundary editing");s.job.finish(s.job.ticket,s.revision,ErrorCode::none,"done");
    lane.synchronize("applied");ui.refreshSectionEditing();const auto frame=s.currentStateDocument.sectionGains->intervals[1].begin;
    start(frame);move(frame+5000);ui.setViewRange(0,120000);
    expect(!s.appliedBoundaryDrag&&s.manualState()==moved,"changing zoom during a gesture cancels before changing the coordinate mapping");
    int seeks=0;ui.setTransport(0,true,{},"transport");ui.onRequestSeek=[&](int64_t,const juce::String&){++seeks;return juce::String();};
    click(ui,ui.rulerBounds().getCentre().toFloat());expect(seeks==1&&s.manualState()==moved,"ruler seeking remains independent of applied-region editing");
    ui.setViewRange(0,240000);mode->setSelectedId(1,juce::sendNotificationSync);
    expect(!lane.appliedBoundaryHandle(point(frame).toInt()-lane.getPosition()),"section selection mode cannot accidentally move applied-region handles");
    const auto key=s.currentStateDocument.sectionGains->audioKey();draw(ui,x(160000),x(190000));
    expect(s.sectionDocument.map().sections.size()==3&&s.currentStateDocument.sectionGains->audioKey()==key,"unchanged waveform drawing edits annotations while preserving applied regions");
    ui.removeFromDesktop();
}
